import QtQuick
import QtQuick.Controls

// Themed tooltip. The bare attached `ToolTip.visible`/`ToolTip.text` renders
// the installed Basic style verbatim: a square-cornered panel with
// `palette.toolTipBase`/`palette.toolTipText`, which on the dark leg leaks a
// pure-white panel with near-black ink onto a (30,30,30) window (R134).
// Opt a site in with `ToolTip.toolTip: KosToolTip {}` alongside the attached
// visible/text.
// The reference has no tooltip at all (R063), so the radius and the two panel
// literals are OUR choice, documented here: radius 6 (the hover/hairline
// family), dark panel #3C3C3C (the tahoe elevated-lift token over #1E1E1E),
// light panel #F2F2F2 (one step below the white plane), ink = the leg's
// labelPrimary, hairline = the leg's separator token.
ToolTip {
    id: control

    padding: 6

    background: Rectangle {
        color: AppTheme.dark ? "#3C3C3C" : "#F2F2F2"
        radius: 6
        border.width: 1
        border.color: AppTheme.dark
            ? Qt.rgba(1, 1, 1, 0.10)
            : Qt.rgba(0, 0, 0, 0.12)
    }

    contentItem: Text {
        text: control.text
        font: control.font
        color: AppTheme.dark ? "#F2F2F2" : "#000000"
        elide: Text.ElideRight
        verticalAlignment: Text.AlignVCenter
    }
}

